"""Итог нового опыта; старые принятые каталоги не обновляются."""
import argparse
import hashlib
import json
from pathlib import Path

R = Path(__file__).resolve().parents[1]
O = R / 'simulation/experiments/tda48'
def read(p): return json.loads(p.read_text())
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()

if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('--guitar-run', type=Path, required=True)
    ng = ap.add_mutually_exclusive_group(required=True)
    ng.add_argument('--noise-run', type=Path)
    ng.add_argument('--noise-access-failure', type=Path)
    a = ap.parse_args()
    a.guitar_run = a.guitar_run.resolve()
    if a.noise_run:
        a.noise_run = a.noise_run.resolve()
    assert not (O / 'summary.json').exists(), 'Итог уже сохранён; новый опыт вести отдельно'
    guitar = read(a.guitar_run / 'full/results.json')
    noise = read(a.noise_run / 'full/results.json') if a.noise_run else None
    access_failure = read(a.noise_access_failure) if a.noise_access_failure else None
    accuracy = read(O / 'noise_accuracy.json')
    reference = read(O / 'noise_long_fast_f64/metrics.json')
    assert guitar['complete'] and reference['complete']
    assert noise is None or noise['complete']
    accepted = R / 'simulation/experiments/rate48/accepted_20260928'
    manifest = read(accepted / 'manifest.json')
    for name,h in manifest['files'].items():
        assert sha(accepted/name) == h['sha256'], name
    host = {p.stem:read(p) for p in sorted((O/'guitar').glob('*.json'))}
    assert all(j['mismatches_output_current_previous_decisions']==[0,0,0,0] for j in host.values())
    result = dict(structure='BoundedState<3,7>, BDF2/48k; same laws, both memories, early exit, no LUT/substeps/extra attempts',
                  guitar_run=str(a.guitar_run.relative_to(R)), noise_run=str(a.noise_run.relative_to(R)) if a.noise_run else None,
                  tda_guitar=guitar, noise_candidate_hardware=noise, noise_accuracy=accuracy,
                  noise_hardware_access_failure=access_failure,
                  noise_host={p.stem:read(p) for p in sorted((O/'noise_repair').glob('*.json'))},
                  noise_candidate_guitar_host={p.stem:read(p) for p in sorted((O/'guitar_noise_repair').glob('*.json'))},
                  guitar_block_bounds=read(a.guitar_run/'full/block_bounds.json'),
                  guitar_queue_bounds=read(a.guitar_run/'full/queue_bounds.json'),
                  original_noise_events={k:read(O/'noise_long'/f'{k}.json')['local_overruns'] for k in host},
                  guitar_host=host, exact_f64_reference=reference,
                  accepted_snapshot_verified=True, accepted_manifest_sha256=sha(accepted/'manifest.json'),
                  default_kernel='bounded48.rs: TDA reuse', noise_candidate='bounded48_noise.rs: optional noise48-candidate feature; separate from default kernel',
                  full_audio_runtime_qualified=False)
    (O/'summary.json').write_text(json.dumps(result,indent=2)+'\n')
    lines = ['# Полировка TDA и шумовая проверка BDF2/48 кГц', '',
             'Рабочая архитектура не менялась. Пакет TDA переиспользует насыщение напряжения, степени и корни между уравнением и кривизной, готовит историю/границы TDA один раз на блок и специализирует его скалярный шаг. Порядок чувствительных операций f32 сохранён. Корень токового ограничения переиспользуется только при одинаковом нормированном аргументе: умножение на обратную величину и деление могут округляться по-разному.', '',
             'До трёх попыток с ранним выходом, физические законы и оба слоя памяти прежние. Полная гитара каждого уровня: 10 643 479 отсчётов / 221,739146 с. Выход, 28 текущих/предыдущих состояний и счётчики кандидата побитово совпали с принятой базой на каждом host-шаге; шесть синусовых траекторий совпали также с прежними сохранёнными файлами. Старые отрицательные f64-проверки 4/6 сохраняются.', '',
             '## Реальный парный RAM-замер полной гитары', '',
             'Оба участника делают один шаг 48 кГц. Контроль — исходник, побайтно совпадающий с принятым снимком 2026-09-28. Порядок вызовов чередуется каждый отсчёт. Здесь такты CPU на выход; DMA/I/O, FIR и кабинет не входят.', '',
             '| Вход | TDA / принятая база, средние такты | Выигрыш | Максимум TDA / базы | Худшее окно64 TDA / базы, на выход |',
             '|---|---:|---:|---:|---:|']
    for key,row in guitar['levels'].items():
        x,y=row['optimized48'],row['accepted48']
        lines.append(f"| {key} | {x['mean_cycles']:.1f} / {y['mean_cycles']:.1f} | {row['mean_saving_percent']:.3f}% | {x['maximum_cycles']} / {y['maximum_cycles']} | {x['max_rolling64_cycles']/64:.1f} / {y['max_rolling64_cycles']/64:.1f} |")
    lines += ['', 'Все 650 порций сохранены. Концы порций обеих моделей сверены с host; полное совпадение памяти и статусы остановок/невязки — в `full/results.json`. Проверены входной хеш каждого PCM-слова, verify_image, защита стека и возврат штатного приложения после reset run. Flash не писалась. Песочница сначала не открыла USB; этот журнал сохранён отдельно, успешные пробы выполнены с доступом к ST-Link.', '',
              f"Серия: `{a.guitar_run.relative_to(R)}`. Исходники и ELF закреплены внутри серии. Последующие изменения экспериментального шумового варианта не подменяют измеренный исходник TDA.", '',
              'На 1 В остаются 1883 отдельных отсчёта дороже 12500 тактов, но ни одно фактически измеренное скользящее окно 64 отсчётов не превышает общий CPU-бюджет; у парной базы таких окон 97. Это результат данной записи, не универсальная граница времени.', '',
              'По гистограммам и точным суммам порций повторены прежние консервативные оценки: любой блок 512 отсчётов сильной записи ограничен 12423,5 такта/выход, блок 1024 — 12164,6. Для равномерно поступающей непрерывной очереди верхняя граница дополнительной накопленной работы соответствует 3 отсчётам при бюджете 12500, но 1093 при бюджете ядра 10000 (22,757 мс). Это верхние оценки по записи, а не измеренная DMA-задержка. Полный тракт не квалифицирован; файлы `block_bounds.json` и `queue_bounds.json` лежат внутри серии.', '',
              '## Шум: численная ошибка, невязка и время — разные результаты', '',
              'Прежний 250-мВ шум проверен двумя способами: 512 концов шагов с той же длительностью 10,667 мс и все прежние 1024 значения на новой сетке. Отказов/локальных превышений нет; независимая полная MNA f64/48 проходит прежние строгие проверки. Пики к ней 0,371 / 1,414 мВ. Длинный шум: 10 с детерминированного PCM и 1 с отпускания, все три уровня.', '',
              'У принятой базы и пакета TDA на 1 В обнаружены пять превышений локальной невязки, но не NaN/Inf и не остановки. Первый отсчёт 156044: IC3A, остаток −0,835 В, нормированная невязка 0,05568. Это не дефект TDA. Newton прыгает через нижнюю границу slew: 12,900521 → 12,602814 → 13,125801 → 12,602814 В. Полная f64 при той же сохранённой истории даёт 12,854760 В и невязку <1e-12. Мгновенный TDA-выход почти совпадает, но внутренний полюс IC3A ошибочен примерно на 2,5 В.', '',
              'Отдельный `bounded48_noise.rs` согласует явный старт IC3A с границей slew: четверть расстояния от граничного напряжения к значению его физического закона. Это начальная оценка, не дополнительная Newton-поправка. Предел до трёх сохранён; вычисление закона старта включено в счётчики. На первом событии три поправки приводят к 12,854760 В. На полной гитаре выход и обе памяти этого варианта также побитово совпали с базой. Счётчики на 1 В отличаются: в IC3A на всю запись добавилось 45 вычислений закона, 22 попытки и 22 поправки; разность накопленных счётчиков сохраняется в следующих шагах. На сильном шуме собственная траектория меняется, и её точность проверяется отдельно. В основной `bounded48.rs` этот старт пока не включён. На длинном шуме 100/250 мВ оба варианта проходят без превышений; на 1 В экспериментальный старт убрал все пять, остановок нет.']
    if noise:
        lines += ['', '| Шум | Средние такты кандидата / базы | Максимум кандидата / базы | Превышения невязки кандидата / базы |',
                  '|---|---:|---:|---:|---:|']
    for key,row in (noise['levels'].items() if noise else []):
        x,y=row['optimized48'],row['accepted48']
        lines.append(f"| {key} | {x['mean_cycles']:.1f} / {y['mean_cycles']:.1f} | {x['maximum_cycles']} / {y['maximum_cycles']} | {x['local_overruns']} / {y['local_overruns']} |")
    if noise is None:
        lines += ['', '**Аппаратный шумовой замер не выполнен.** Свежая сборка и 53 release-теста завершены, но запуск RAM-пробы не состоялся: автоматическая проверка доступа не смогла обновить токен после выхода/смены аккаунта. Это сбой проверки доступа, не численный отказ и не отказ платы. Причина сохранена в `noise_ram_access_failure.json`; проверка не обходилась. Последнее подтверждённое состояние платы — успешный возврат штатного приложения после полного гитарного замера. Такты шумовому кандидату не приписываются. После восстановления доступа подготовить новую серию из актуальных исходников.']
    lines += ['', 'Полный глобальный f64-Newton остановился на отсчёте 80; успешный префикс и отказ сохранены, точность всей записи ему не приписывается. Длинный арбитр — точная сокращённая f64-система от нулевой собственной памяти с проверкой исходной полной MNA-невязки на каждом шаге: максимум нормированной невязки 1,003e-11, KCL 1,003e-13 А. Ускорение офлайн-проверки убирает расчёт чужих блоков на локальных пробах; на 49152 шагах исходный и ускоренный варианты точной сокращённой f64 расходятся менее 0,3 нВ. Это не две независимые физические модели и не успешный глобальный full-MNA Newton. Поиск длины и дополнительные итерации относятся только к офлайн-арбитру, не прошивке.', '',
              '| Сильный шум к точному f64/48 | RMS, В | Относительный RMS | Пик, В | Пик отпускания, В |',
              '|---|---:|---:|---:|---:|']
    for name,v in accuracy['comparisons'].items():
        lines.append(f"| {name} | {v['rms_v']:.9g} | {100*v['relative_rms']:.6g}% | {v['peak_v']:.9g} | {v['release_peak_v']:.9g} |")
    lines += ['', 'Пик кандидата 72,581 мВ и 117 отсчётов выше прежних 10 мВ: старая пиковая проверка не проходит, несмотря на отсутствие превышений локальной невязки. Пики собственной памяти кандидата: ёмкости 71,916 мВ, полюса 73,768 мВ; прежняя база сохраняет только редкие контрольные точки памяти, их максимум нельзя сравнивать как равноправный полный пик. На отпускании пик выхода 0,053 мВ. Слухового сравнения этого шумового варианта не было.']
    lines += ['', 'Все 528000 шагов арбитра завершены. Ошибки всех 28 координат и обоих слоёв памяти кандидата, окон 1/10/100/1000 мс и прежний 10-мВ счётчик — в `noise_accuracy.json`. Малую невязку не считаем доказательством точной памяти. Пиковая численная граница 10 мВ не превращается в слуховую норму и не ослабляется. Отдельный шумовой кандидат остаётся экспериментальным: его среднее/пики на шуме не заменяют полного аппаратного бюджета этого варианта на гитаре и не доказывают слуховую эквивалентность.', '',
              '## Воспроизведение и следующие шаги', '',
              'Для парного host-контроля: `tda48_compare` с признаком `tda48-baseline`; для отдельного старта IC3A — `noise48-candidate`. Каталог вывода и путь входа задаются аргументами. RAM-серии готовит `simulation/run_tda48_hardware.py`, анализ — `simulation/analyze_tda48_hardware.py`. Старые архивы не перезаписываются.', '',
              'Генерация только коэффициентов: `simulation/generate_rate48_coefficients.py --out НОВЫЙ_КАТАЛОГ`. Оба файла воспроизведены побитово; алгоритм не копируется из 96 кГц. Старый `generate_rate48.py` останавливается до записи при наличии самостоятельной полировки.', '',
              'Далее: решить вопрос включения шумового старта после полного аппаратного контроля его цены на гитаре; кабинет/выходной FIR и совместный бюджет. IR остаётся прежним — 2400 коэффициентов на 48 кГц. Блочная свёртка на MCU и DMA-аудиотракт этим опытом не реализованы. Архитектурный выбор 48 кГц не пересматривается.']
    (O/'report.md').write_text('\n'.join(lines)+'\n')
    print(O/'report.md')
